import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"🎨 01 · 前端（AI 交互层）","description":"","frontmatter":{},"headers":[],"relativePath":"07-开发岗-前后端与全栈/01-前端.md","filePath":"07-开发岗-前后端与全栈/01-前端.md","lastUpdated":1786806808000}'),i={name:"07-开发岗-前后端与全栈/01-前端.md"};function l(n,t,s,c,h,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="🎨-01-·-前端-ai-交互层" tabindex="-1">🎨 01 · 前端（AI 交互层） <a class="header-anchor" href="#🎨-01-·-前端-ai-交互层" aria-label="Permalink to &quot;🎨 01 · 前端（AI 交互层）&quot;">​</a></h1><blockquote><p>AI 产品的「脸面」。Chat UI、流式输出、多模态输入是 AI 前端特有能力。</p></blockquote><hr><h2 id="一、核心考点" tabindex="-1">一、核心考点 <a class="header-anchor" href="#一、核心考点" aria-label="Permalink to &quot;一、核心考点&quot;">​</a></h2><ul><li><strong>框架</strong>：React / Vue（组件化、状态管理 Redux/Pinia）。</li><li><strong>工程</strong>：TypeScript、构建（Vite/Webpack）、性能优化、可访问性。</li><li><strong>网络</strong>：fetch、WebSocket、SSE（流式）、拦截器。</li><li><strong>状态与渲染</strong>：虚拟列表（长对话）、Diff 算法。</li></ul><h2 id="二、ai-专属能力" tabindex="-1">二、AI 专属能力 <a class="header-anchor" href="#二、ai-专属能力" aria-label="Permalink to &quot;二、AI 专属能力&quot;">​</a></h2><ul><li><strong>流式渲染</strong>：用 SSE/WebSocket 接收 LLM token 并逐字渲染（打字机效果），保留可中断/取消。</li><li><strong>Chat UI</strong>：消息流、Markdown 渲染、代码高亮、思维链展示、工具调用可视化。</li><li><strong>多模态输入</strong>：上传图片/文件 → 切片/预览 → 传给后端。</li><li><strong>错误处理与降级</strong>：请求失败、超时、模型不可用时的友好提示与重试。</li><li><strong>Prompt 输入优化</strong>：输入框、模板、历史管理。</li></ul><h2 id="三、高频追问" tabindex="-1">三、高频追问 <a class="header-anchor" href="#三、高频追问" aria-label="Permalink to &quot;三、高频追问&quot;">​</a></h2><p><strong>Q1：SSE 和 WebSocket 怎么选做 AI 流式？</strong></p><blockquote><p>SSE 单向（服务端→客户端）更简单、基于 HTTP、自动重连，适合 LLM 流式输出；WebSocket 双向、适合需要客户端实时发指令/多轮交互的场景。</p></blockquote><p><strong>Q2：长对话前端怎么不卡？</strong></p><blockquote><p>虚拟列表只渲染可视区、分片加载、消息分组；超长历史可折叠/摘要；避免每次全量重渲染。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-后端">02-后端</a></p>',14)])])}const _=a(i,[["render",l]]);export{u as __pageData,_ as default};
